"""Generated by the QA agent for STORY-101: Sign in securely, with lockout after failed attempts."""
import re

from playwright.sync_api import expect

from nilebank_helpers import sign_in


def test_tc_101_01_valid_sign_in_shows_accounts_ui(page):
    """TC-101-01 (UI)"""
    sign_in(page, "amira", "Nile@2026")
    expect(page).to_have_url(re.compile(r".*/dashboard(\?.*)?$"))
    expect(page.get_by_test_id("user-name")).to_have_text("Amira Hassan")


def test_tc_101_02_wrong_password_shows_generic_error_ui(page):
    """TC-101-02 (UI)"""
    sign_in(page, "amira", "wrong-password")
    expect(page.get_by_test_id("login-error")).to_have_text("Invalid username or password.")
    expect(page).to_have_url(re.compile(r".*/login(\?.*)?$"))


def test_tc_101_03_account_locks_after_three_failures_api(bank):
    """TC-101-03 (API)"""
    for _ in range(3):
        bank.post("/api/auth/login", json={"username": "amira", "password": "wrong"})
    r = bank.post("/api/auth/login", json={"username": "amira", "password": "Nile@2026"})
    assert r.status_code == 423, f"expected 423 locked after 3 failures, got {r.status_code}: {r.text}"


def test_tc_101_04_unknown_user_gets_same_error_api(bank):
    """TC-101-04 (API)"""
    unknown = bank.post("/api/auth/login", json={"username": "nobody", "password": "x"})
    wrong = bank.post("/api/auth/login", json={"username": "omar", "password": "x"})
    assert unknown.status_code == wrong.status_code == 401
    assert unknown.json()["detail"] == wrong.json()["detail"]
